[metadata] {"type": "create", "filePath": "/app/benchmark/presentation.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Global CO₂ Emissions: Trends, Regional Shifts, and Per Capita Inequalities</title>
    <link href="https://fonts.googleapis.com/css2?family=Syne:wght@400;600;700;800&family=DM+Sans:ital,wght@0,400;0,500;0,600;0,700;1,400&display=swap" rel="stylesheet">
    <style>
        /* ===========================================
           VIEWPORT FITTING: MANDATORY BASE STYLES
           =========================================== */
        html, body {
            height: 100%;
            overflow-x: hidden;
        }
        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }
        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
        }
        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }
        :root {
            --title-size: clamp(1.5rem, 5vw, 4rem);
            --h2-size: clamp(1.25rem, 3.5vw, 2.5rem);
            --h3-size: clamp(1rem, 2.5vw, 1.75rem);
            --body-size: clamp(0.75rem, 1.5vw, 1.125rem);
            --small-size: clamp(0.65rem, 1vw, 0.875rem);
            --slide-padding: clamp(1rem, 4vw, 4rem);
            --content-gap: clamp(0.5rem, 2vw, 2rem);
            --element-gap: clamp(0.25rem, 1vw, 1rem);
        }
        .card, .container, .content-box {
            max-width: min(90vw, 1000px);
            max-height: min(80vh, 700px);
        }
        .feature-list, .bullet-list { gap: clamp(0.4rem, 1vh, 1rem); }
        .feature-list li, .bullet-list li { font-size: var(--body-size); line-height: 1.4; }
        .grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr));
            gap: clamp(0.5rem, 1.5vw, 1rem);
        }
        img, .image-container {
            max-width: 100%;
            max-height: min(50vh, 400px);
            object-fit: contain;
        }
        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 3vw, 2rem);
                --content-gap: clamp(0.4rem, 1.5vw, 1rem);
                --title-size: clamp(1.25rem, 4.5vw, 2.5rem);
                --h2-size: clamp(1rem, 3vw, 1.75rem);
            }
        }
        @media (max-height: 600px) {
            :root {
                --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
                --content-gap: clamp(0.3rem, 1vw, 0.75rem);
                --title-size: clamp(1.1rem, 4vw, 2rem);
                --body-size: clamp(0.7rem, 1.2vw, 0.95rem);
            }
            .nav-dots, .keyboard-hint, .decorative { display: none; }
        }
        @media (max-height: 500px) {
            :root {
                --slide-padding: clamp(0.4rem, 2vw, 1rem);
                --title-size: clamp(1rem, 3.5vw, 1.5rem);
                --h2-size: clamp(0.9rem, 2.5vw, 1.25rem);
                --body-size: clamp(0.65rem, 1vw, 0.85rem);
            }
        }
        @media (max-width: 600px) {
            :root { --title-size: clamp(1.25rem, 7vw, 2.5rem); }
            .grid { grid-template-columns: 1fr; }
        }
        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }

        /* ===========================================
           THEME: DARK ANALYTICAL
           Authoritative data-forward style for policy analysts
           =========================================== */
        :root {
            --bg-primary: #080d1a;
            --bg-card: #0f1729;
            --bg-card-alt: #141e33;
            --text-primary: #e8ecf4;
            --text-secondary: #8899b4;
            --text-muted: #4a5a78;
            --accent-cyan: #38bdf8;
            --accent-amber: #f59e0b;
            --accent-red: #ef4444;
            --accent-green: #34d399;
            --accent-violet: #a78bfa;
            --font-display: 'Syne', sans-serif;
            --font-body: 'DM Sans', sans-serif;
            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-normal: 0.6s;
        }

        * { margin: 0; padding: 0; box-sizing: border-box; }

        body {
            font-family: var(--font-body);
            background: var(--bg-primary);
            color: var(--text-primary);
            -webkit-font-smoothing: antialiased;
        }

        h1, h2, h3 { font-family: var(--font-display); font-weight: 800; }
        h2 { font-size: var(--h2-size); line-height: 1.15; margin-bottom: var(--content-gap); }
        h3 { font-size: var(--h3-size); line-height: 1.2; }

        /* ===========================================
           PROGRESS BAR
           =========================================== */
        .progress-bar {
            position: fixed; top: 0; left: 0; height: 3px;
            background: linear-gradient(90deg, var(--accent-cyan), var(--accent-amber));
            z-index: 1000; transition: width 0.3s ease; width: 0%;
        }

        /* ===========================================
           NAV DOTS
           =========================================== */
        .nav-dots {
            position: fixed; right: clamp(0.5rem, 1.5vw, 1.5rem);
            top: 50%; transform: translateY(-50%); z-index: 1000;
            display: flex; flex-direction: column; gap: 8px;
        }
        .nav-dot {
            width: 8px; height: 8px; border-radius: 50%;
            background: var(--text-muted); cursor: pointer;
            transition: all 0.3s ease; border: none;
        }
        .nav-dot.active { background: var(--accent-cyan); transform: scale(1.4); }

        /* ===========================================
           ANIMATIONS
           =========================================== */
        .reveal {
            opacity: 0; transform: translateY(25px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }
        .slide.visible .reveal { opacity: 1; transform: translateY(0); }
        .reveal:nth-child(1) { transition-delay: 0.05s; }
        .reveal:nth-child(2) { transition-delay: 0.15s; }
        .reveal:nth-child(3) { transition-delay: 0.25s; }
        .reveal:nth-child(4) { transition-delay: 0.35s; }
        .reveal:nth-child(5) { transition-delay: 0.45s; }
        .reveal:nth-child(6) { transition-delay: 0.55s; }

        .reveal-scale {
            opacity: 0; transform: scale(0.92);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }
        .slide.visible .reveal-scale { opacity: 1; transform: scale(1); }

        .reveal-left {
            opacity: 0; transform: translateX(-30px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }
        .slide.visible .reveal-left { opacity: 1; transform: translateX(0); }

        /* ===========================================
           SLIDE BACKGROUNDS
           =========================================== */
        .slide {
            background: var(--bg-primary);
            background-image:
                radial-gradient(ellipse at 15% 85%, rgba(56, 189, 248, 0.04) 0%, transparent 50%),
                radial-gradient(ellipse at 85% 15%, rgba(245, 158, 11, 0.03) 0%, transparent 50%);
        }

        /* Grid overlay for data slides */
        .slide::before {
            content: ''; position: absolute; inset: 0;
            background-image:
                linear-gradient(rgba(56, 189, 248, 0.015) 1px, transparent 1px),
                linear-gradient(90deg, rgba(56, 189, 248, 0.015) 1px, transparent 1px);
            background-size: 60px 60px; pointer-events: none; z-index: 0;
        }

        .slide > * { position: relative; z-index: 1; }

        /* ===========================================
           SLIDE 1: TITLE
           =========================================== */
        .title-slide {
            justify-content: center; align-items: center; text-align: center;
            background:
                radial-gradient(ellipse at 50% 50%, rgba(56, 189, 248, 0.08) 0%, transparent 60%),
                radial-gradient(ellipse at 20% 80%, rgba(245, 158, 11, 0.05) 0%, transparent 40%),
                radial-gradient(ellipse at 80% 20%, rgba(167, 139, 250, 0.04) 0%, transparent 40%),
                var(--bg-primary);
        }
        .title-slide::before { display: none; }
        .title-slide h1 {
            font-size: clamp(2rem, 5.5vw, 4.2rem);
            line-height: 1.05; margin-bottom: clamp(0.5rem, 2vw, 1.5rem);
            background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent-cyan) 100%);
            -webkit-background-clip: text; -webkit-text-fill-color: transparent;
            background-clip: text;
        }
        .title-slide .subtitle {
            font-size: clamp(0.85rem, 1.8vw, 1.35rem);
            color: var(--text-secondary); margin-bottom: clamp(1rem, 3vw, 2.5rem);
            font-weight: 400; max-width: 700px;
        }
        .title-slide .scope {
            display: inline-block;
            font-family: var(--font-display); font-weight: 700;
            font-size: clamp(0.8rem, 1.4vw, 1.1rem);
            color: var(--accent-cyan); letter-spacing: 0.15em;
            border: 1px solid rgba(56, 189, 248, 0.3);
            padding: clamp(0.3rem, 0.8vw, 0.6rem) clamp(0.8rem, 2vw, 1.5rem);
            border-radius: 4px; margin-bottom: clamp(0.8rem, 2vw, 1.5rem);
        }
        .title-slide .source {
            font-size: clamp(0.6rem, 0.9vw, 0.8rem);
            color: var(--text-muted); margin-top: clamp(0.5rem, 1.5vw, 1rem);
        }

        /* CO2 molecule decoration */
        .co2-molecule {
            position: absolute; opacity: 0.06;
            top: 15%; right: 12%; width: clamp(120px, 20vw, 280px);
            height: clamp(60px, 10vw, 140px);
        }
        .co2-molecule .atom {
            position: absolute; border-radius: 50%;
            border: 2px solid var(--accent-cyan);
        }
        .co2-molecule .atom.c { width: 50%; height: 80%; top: 10%; left: 25%; border-color: var(--accent-amber); }
        .co2-molecule .atom.o1 { width: 35%; height: 60%; top: 20%; left: 0; }
        .co2-molecule .atom.o2 { width: 35%; height: 60%; top: 20%; right: 0; }

        /* ===========================================
           COMMON CONTENT STYLES
           =========================================== */
        .slide-header {
            display: flex; align-items: flex-start; gap: clamp(0.5rem, 1.5vw, 1.2rem);
            margin-bottom: clamp(0.5rem, 1.5vw, 1.2rem);
        }
        .slide-number {
            font-family: var(--font-display); font-weight: 800;
            font-size: clamp(1.5rem, 4vw, 3rem); color: var(--accent-cyan);
            line-height: 1; opacity: 0.4; min-width: clamp(1.5rem, 3vw, 2.5rem);
        }
        .slide-title-text {
            font-size: clamp(1.1rem, 2.5vw, 2rem);
            line-height: 1.2; font-weight: 800;
        }
        .highlight-cyan { color: var(--accent-cyan); }
        .highlight-amber { color: var(--accent-amber); }
        .highlight-red { color: var(--accent-red); }
        .highlight-green { color: var(--accent-green); }

        .stat-callout {
            display: flex; flex-direction: column; align-items: center;
            padding: clamp(0.5rem, 1.5vw, 1.2rem);
            background: var(--bg-card);
            border: 1px solid rgba(56, 189, 248, 0.15);
            border-radius: 8px;
        }
        .stat-callout .stat-value {
            font-family: var(--font-display); font-weight: 800;
            font-size: clamp(1.5rem, 4vw, 3.5rem);
            line-height: 1;
        }
        .stat-callout .stat-label {
            font-size: var(--small-size);
            color: var(--text-secondary); margin-top: 0.3rem; text-align: center;
        }

        .two-col {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(1rem, 3vw, 2.5rem);
            align-items: start;
        }
        .two-col-wide-left {
            grid-template-columns: 1.2fr 0.8fr;
        }
        .two-col-wide-right {
            grid-template-columns: 0.8fr 1.2fr;
        }

        /* ===========================================
           DATA TABLE STYLES
           =========================================== */
        .data-table {
            width: 100%; border-collapse: collapse;
            font-size: var(--small-size);
        }
        .data-table th {
            font-family: var(--font-display); font-weight: 700;
            text-align: left; padding: clamp(0.3rem, 0.8vw, 0.6rem) clamp(0.4rem, 1vw, 0.8rem);
            border-bottom: 2px solid var(--accent-cyan);
            color: var(--accent-cyan); font-size: clamp(0.6rem, 0.9vw, 0.8rem);
            text-transform: uppercase; letter-spacing: 0.05em;
        }
        .data-table td {
            padding: clamp(0.25rem, 0.6vw, 0.5rem) clamp(0.4rem, 1vw, 0.8rem);
            border-bottom: 1px solid rgba(56, 189, 248, 0.08);
            vertical-align: middle;
        }
        .data-table tr:hover { background: rgba(56, 189, 248, 0.04); }
        .data-table .trend-down { color: var(--accent-green); }
        .data-table .trend-up { color: var(--accent-red); }
        .data-table .trend-stable { color: var(--accent-amber); }

        /* ===========================================
           HORIZONTAL BAR CHART
           =========================================== */
        .bar-chart { width: 100%; }
        .bar-row {
            display: grid;
            grid-template-columns: clamp(70px, 10vw, 110px) 1fr clamp(35px, 5vw, 55px);
            align-items: center; gap: clamp(0.3rem, 0.8vw, 0.6rem);
            margin-bottom: clamp(0.2rem, 0.5vw, 0.5rem);
        }
        .bar-label {
            font-size: clamp(0.55rem, 0.9vw, 0.8rem);
            color: var(--text-secondary); text-align: right;
            font-weight: 500;
        }
        .bar-track {
            height: clamp(14px, 2.2vh, 22px);
            background: rgba(56, 189, 248, 0.06);
            border-radius: 3px; overflow: hidden;
        }
        .bar-fill {
            height: 100%; border-radius: 3px;
            transition: width 1s var(--ease-out-expo);
            width: 0;
        }
        .slide.visible .bar-fill { width: var(--bar-width); }
        .bar-value {
            font-size: clamp(0.55rem, 0.9vw, 0.8rem);
            font-weight: 600; font-family: var(--font-display);
        }

        /* ===========================================
           REGIONAL COMPARISON PANELS
           =========================================== */
        .comparison-panel {
            background: var(--bg-card);
            border: 1px solid rgba(56, 189, 248, 0.12);
            border-radius: 8px; padding: clamp(0.8rem, 2vw, 1.5rem);
        }
        .comparison-panel .year-label {
            font-family: var(--font-display); font-weight: 800;
            font-size: clamp(1.5rem, 3.5vw, 2.8rem);
            color: var(--accent-cyan); margin-bottom: clamp(0.3rem, 1vw, 0.8rem);
        }
        .region-bar {
            display: flex; align-items: center; gap: 0.5rem;
            margin-bottom: clamp(0.2rem, 0.5vw, 0.4rem);
        }
        .region-bar .region-name {
            font-size: clamp(0.55rem, 0.85vw, 0.75rem);
            color: var(--text-secondary); min-width: clamp(60px, 8vw, 90px);
            text-align: right;
        }
        .region-bar .region-fill {
            height: clamp(16px, 2.5vh, 24px);
            border-radius: 3px;
            transition: width 1s var(--ease-out-expo);
            display: flex; align-items: center; justify-content: flex-end;
            padding-right: 6px;
            font-size: clamp(0.5rem, 0.7vw, 0.65rem);
            font-weight: 600; color: var(--bg-primary);
            width: 0;
        }
        .slide.visible .region-fill { width: var(--region-width); }

        /* ===========================================
           MAP LEGEND
           =========================================== */
        .map-legend {
            display: flex; align-items: center; gap: clamp(0.5rem, 1.5vw, 1rem);
            flex-wrap: wrap;
        }
        .legend-item {
            display: flex; align-items: center; gap: 0.3rem;
            font-size: var(--small-size);
        }
        .legend-swatch {
            width: clamp(12px, 1.5vw, 18px);
            height: clamp(12px, 1.5vw, 18px);
            border-radius: 3px;
        }

        /* ===========================================
           ENERGY MIX TABLE
           =========================================== */
        .energy-table {
            width: 100%; border-collapse: separate; border-spacing: 0;
            font-size: var(--small-size);
            overflow: hidden; border-radius: 8px;
            border: 1px solid rgba(56, 189, 248, 0.12);
        }
        .energy-table th {
            font-family: var(--font-display); font-weight: 700;
            padding: clamp(0.35rem, 0.8vw, 0.6rem) clamp(0.4rem, 1vw, 0.8rem);
            background: var(--bg-card-alt); text-align: center;
            font-size: clamp(0.55rem, 0.8vw, 0.75rem);
            text-transform: uppercase; letter-spacing: 0.05em;
        }
        .energy-table td {
            padding: clamp(0.3rem, 0.7vw, 0.5rem) clamp(0.4rem, 1vw, 0.8rem);
            border-top: 1px solid rgba(56, 189, 248, 0.06);
            text-align: center;
        }
        .energy-table .group-header td {
            background: rgba(56, 189, 248, 0.06);
            font-family: var(--font-display); font-weight: 700;
            text-align: left; color: var(--accent-cyan);
            font-size: clamp(0.6rem, 0.85vw, 0.75rem);
        }
        .energy-table .country-row td:first-child {
            text-align: left; font-weight: 600;
        }

        /* ===========================================
           TAKEAWAY BULLETS
           =========================================== */
        .takeaway-list {
            list-style: none; counter-reset: takeaway;
        }
        .takeaway-list li {
            counter-increment: takeaway;
            display: flex; align-items: flex-start; gap: clamp(0.5rem, 1.2vw, 1rem);
            margin-bottom: clamp(0.4rem, 1vh, 0.8rem);
            font-size: clamp(0.7rem, 1.2vw, 0.95rem);
            line-height: 1.45;
        }
        .takeaway-list li::before {
            content: counter(takeaway);
            font-family: var(--font-display); font-weight: 800;
            font-size: clamp(0.9rem, 1.8vw, 1.4rem);
            color: var(--accent-cyan); line-height: 1;
            min-width: clamp(1.2rem, 2vw, 1.8rem);
        }

        /* ===========================================
           FIGURE IMAGES
           =========================================== */
        .figure-container {
            border-radius: 6px; overflow: hidden;
            border: 1px solid rgba(56, 189, 248, 0.12);
            background: var(--bg-card);
        }
        .figure-container img {
            width: 100%; height: auto;
            max-height: min(42vh, 360px);
            object-fit: contain; display: block;
        }
        .figure-caption {
            font-size: clamp(0.5rem, 0.7vw, 0.65rem);
            color: var(--text-muted); padding: 0.3rem 0.5rem;
            text-align: center;
        }

        /* ===========================================
           FOOTER
           =========================================== */
        .slide-footer {
            position: absolute; bottom: clamp(0.4rem, 1vw, 0.8rem);
            left: var(--slide-padding); right: var(--slide-padding);
            display: flex; justify-content: space-between; align-items: center;
            font-size: clamp(0.5rem, 0.7vw, 0.65rem);
            color: var(--text-muted); z-index: 2;
        }

        /* ===========================================
           INLINE STATS ROW
           =========================================== */
        .stats-row {
            display: flex; gap: clamp(0.5rem, 1.5vw, 1.2rem);
            flex-wrap: wrap;
        }
        .stats-row .stat-callout { flex: 1; min-width: clamp(100px, 15vw, 180px); }

        /* ===========================================
           TIMELINE
           =========================================== */
        .timeline {
            display: flex; align-items: center; gap: 0;
            position: relative; padding: clamp(0.5rem, 1.5vw, 1rem) 0;
        }
        .timeline-line {
            flex: 1; height: 2px;
            background: linear-gradient(90deg, var(--accent-cyan), var(--accent-amber), var(--accent-red));
            position: relative;
        }
        .timeline-point {
            position: absolute; top: 50%; transform: translate(-50%, -50%);
            display: flex; flex-direction: column; align-items: center;
        }
        .timeline-dot {
            width: clamp(8px, 1.2vw, 12px); height: clamp(8px, 1.2vw, 12px);
            border-radius: 50%; border: 2px solid;
        }
        .timeline-year {
            font-family: var(--font-display); font-weight: 700;
            font-size: clamp(0.55rem, 0.8vw, 0.7rem);
            margin-top: clamp(0.3rem, 0.5vw, 0.5rem);
        }
        .timeline-value {
            font-size: clamp(0.5rem, 0.7vw, 0.6rem);
            color: var(--text-secondary);
        }
    </style>
</head>
<body>
    <div class="progress-bar"></div>
    <nav class="nav-dots"></nav>

    <!-- ===========================================
         SLIDE 1: TITLE
         =========================================== -->
    <section class="slide title-slide">
        <div class="co2-molecule">
            <div class="atom c"></div>
            <div class="atom o1"></div>
            <div class="atom o2"></div>
        </div>
        <h1 class="reveal">Global CO₂ Emissions</h1>
        <p class="subtitle reveal">Trends, Regional Shifts, and Per Capita Inequalities</p>
        <div class="scope reveal">1750 — 2024</div>
        <p class="source reveal">Data: Global Carbon Budget 2025 &middot; NASA &middot; Our World in Data</p>
    </section>

    <!-- ===========================================
         SLIDE 2: ATMOSPHERIC CO₂ MILESTONE
         =========================================== -->
    <section class="slide">
        <div class="slide-content" style="justify-content: flex-start; padding-top: clamp(1.5rem, 4vh, 3rem);">
            <div class="slide-header reveal">
                <span class="slide-number">01</span>
                <span class="slide-title-text">Atmospheric CO₂ Reaches <span class="highlight-cyan">429 ppm</span> — 50% Above Pre-Industrial Levels</span>
            </div>

            <div class="stats-row reveal" style="margin-bottom: clamp(0.5rem, 1.5vw, 1.2rem);">
                <div class="stat-callout">
                    <div class="stat-value highlight-cyan">429</div>
                    <div class="stat-label">ppm (Feb 2026)</div>
                </div>
                <div class="stat-callout">
                    <div class="stat-value highlight-amber">280</div>
                    <div class="stat-label">ppm pre-industrial</div>
                </div>
                <div class="stat-callout">
                    <div class="stat-value highlight-red">+53%</div>
                    <div class="stat-label">increase since 1750</div>
                </div>
