           JAVASCRIPT: SLIDE PRESENTATION CONTROLLER
           =========================================== -->
    <script>
        class SlidePresentation {
            constructor() {
                this.slides = document.querySelectorAll('.slide');
                this.currentSlide = 0;
                this.isScrolling = false;
                this.setupIntersectionObserver();
                this.setupKeyboardNav();
                this.setupWheelNav();
                this.setupTouchNav();
                this.setupProgressBar();
                this.setupNavDots();
            }

            setupIntersectionObserver() {
                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');
                            const idx = Array.from(this.slides).indexOf(entry.target);
                            if (idx !== -1) {
                                this.currentSlide = idx;
                                this.updateNavDots();
                                this.updateProgressBar();
                            }
                        }
                    });
                }, { threshold: 0.5 });
                this.slides.forEach(slide => observer.observe(slide));
            }

            goToSlide(index) {
                if (index < 0 || index >= this.slides.length) return;
                this.currentSlide = index;
                this.slides[index].scrollIntoView({ behavior: 'smooth' });
                this.updateNavDots();
                this.updateProgressBar();
            }

            nextSlide() { this.goToSlide(this.currentSlide + 1); }
            prevSlide() { this.goToSlide(this.currentSlide - 1); }

            setupKeyboardNav() {
                document.addEventListener('keydown', (e) => {
                    if (e.key === 'ArrowRight' || e.key === ' ' || e.key === 'PageDown') {
                        e.preventDefault(); this.nextSlide();
                    } else if (e.key === 'ArrowLeft' || e.key === 'PageUp') {
                        e.preventDefault(); this.prevSlide();
                    } else if (e.key === 'Home') {
                        e.preventDefault(); this.goToSlide(0);
                    } else if (e.key === 'End') {
                        e.preventDefault(); this.goToSlide(this.slides.length - 1);
                    }
                });
            }

            setupWheelNav() {
                let lastScroll = 0;
                document.addEventListener('wheel', (e) => {
                    const now = Date.now();
                    if (now - lastScroll < 800) return;
                    lastScroll = now;
                    if (e.deltaY > 0) this.nextSlide();
                    else if (e.deltaY < 0) this.prevSlide();
                }, { passive: true });
            }

            setupTouchNav() {
                let startY = 0;
                document.addEventListener('touchstart', (e) => { startY = e.touches[0].clientY; }, { passive: true });
                document.addEventListener('touchend', (e) => {
                    const diff = startY - e.changedTouches[0].clientY;
                    if (Math.abs(diff) > 50) {
                        if (diff > 0) this.nextSlide();
                        else this.prevSlide();
                    }
                }, { passive: true });
            }

            setupProgressBar() {
                this.progressBar = document.querySelector('.progress-bar');
                this.updateProgressBar();
            }

            updateProgressBar() {
                if (!this.progressBar) return;
                const pct = ((this.currentSlide + 1) / this.slides.length) * 100;
                this.progressBar.style.width = pct + '%';
            }

            setupNavDots() {
                const nav = document.querySelector('.nav-dots');
                if (!nav) return;
                this.slides.forEach((_, i) => {
                    const dot = document.createElement('button');
                    dot.className = 'nav-dot';
                    dot.setAttribute('aria-label', `Go to slide ${i + 1}`);
                    dot.addEventListener('click', () => this.goToSlide(i));
                    nav.appendChild(dot);
                });
                this.navDots = nav.querySelectorAll('.nav-dot');
                this.updateNavDots();
            }

            updateNavDots() {
                if (!this.navDots) return;
                this.navDots.forEach((dot, i) => {
                    dot.classList.toggle('active', i === this.currentSlide);
                });
            }
        }

        new SlidePresentation();
    </script>
